import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.DoCD98hS.js";const i=JSON.parse('{"title":"选组件、工具库与模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/index.md","filePath":"modules/index.md","lastUpdated":1795666581000}'),c={name:"modules/index.md"};function s(r,t,n,l,p,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="选组件、工具库与模板" tabindex="-1">选组件、工具库与模板 <a class="header-anchor" href="#选组件、工具库与模板" aria-label="Permalink to &quot;选组件、工具库与模板&quot;">​</a></h1><p>选择你正在做的事，再按框架找到适合的示例。</p><table tabindex="0"><thead><tr><th>我想做什么</th><th>从哪里开始</th></tr></thead><tbody><tr><td>看组件实际效果</td><td><a href="./demos.html">在线演示</a></td></tr><tr><td>查找适用于 Vue 2、Vue 3 或 React 的公共组件</td><td><a href="./components.html">组件包</a></td></tr><tr><td>使用加载器、属性面板或其他工具</td><td><a href="./libs.html">基础库</a></td></tr><tr><td>找后台、H5 或大屏的参考模板</td><td><a href="./templates.html">应用模板</a></td></tr><tr><td>给主应用加 Tab 和子应用保活</td><td><a href="./../guide/micro-frontend-tabs.html">微前端远程 Tab</a></td></tr><tr><td>查阅 Bag 插件化后台</td><td><a href="./docs-and-services.html">专题文档</a></td></tr></tbody></table><p><code>comps-*</code> 主要提供公共组件，<code>libs-*</code> 包含运行时适配和工具，<code>demo-*</code> 用来体验组件，<code>tpl-*</code> 展示完整应用。具体入口和使用方式见各专题；有些库作为普通依赖使用，无需远程加载。</p><h2 id="包结构" tabindex="-1">包结构 <a class="header-anchor" href="#包结构" aria-label="Permalink to &quot;包结构&quot;">​</a></h2><p>按职责分五类，产物目录决定它被怎样引用：</p><table tabindex="0"><thead><tr><th>层级</th><th>目录前缀</th><th>产物目录</th><th>unpkg 入口（占位）</th></tr></thead><tbody><tr><td>加载核心与工具</td><td><code>libs-*</code></td><td><code>dist/</code>，远程用法另带 <code>hel_dist/</code></td><td><a href="https://unpkg.com/@melt-js/libs-core/dist/cdn/index.umd.cjs" target="_blank" rel="noreferrer">libs-core</a></td></tr><tr><td>远程组件</td><td><code>comps-*</code></td><td><code>hel_dist/</code></td><td><a href="https://unpkg.com/@melt-js/comps-vue3/hel_dist/hel-meta.json" target="_blank" rel="noreferrer">comps-vue3</a></td></tr><tr><td>体验示例</td><td><code>demo-*</code></td><td><code>dist/</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue3/dist/index.html" target="_blank" rel="noreferrer">demo-vue3</a></td></tr><tr><td>应用模板</td><td><code>tpl-*</code></td><td><code>dist/</code></td><td><a href="https://unpkg.com/@melt-js/tpl-vue3-admin-ele-vben/dist/index.html" target="_blank" rel="noreferrer">tpl-vue3-admin-ele-vben</a></td></tr><tr><td>独立站点</td><td><code>docs-*</code>、<code>website-*</code></td><td><code>dist/</code> 或站点根</td><td><a href="https://melt-js.github.io/docs-all/dist/index.html" target="_blank" rel="noreferrer">docs-all</a></td></tr></tbody></table><p>单个包展开是同一套形状，四个目录各管一件事：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@melt-js/comps-vue3/</span></span>
<span class="line"><span>├── dist/           打包产物，npm 默认入口</span></span>
<span class="line"><span>├── hel_dist/       HEL 远程产物：hel-meta.json、index.html 与分包</span></span>
<span class="line"><span>├── hel_proxy/      CommonJS / UMD 环境的代理入口</span></span>
<span class="line"><span>└── hel_proxy_es/   ESM 代理入口，import 时用这个</span></span></code></pre></div><p>上表的地址一律按 unpkg 形态写，只作跨环境占位：文档站发布到自建服务器或 GitHub Pages 之后，浏览器端会按当前域名把链接改写到站点自己的镜像目录，不需要为每个环境各维护一份地址。</p><h3 id="业务线与领域包也在-comps-下" tabindex="-1">业务线与领域包也在 <code>comps-*</code> 下 <a class="header-anchor" href="#业务线与领域包也在-comps-下" aria-label="Permalink to &quot;业务线与领域包也在 \`comps-*\` 下&quot;">​</a></h3><p>五类前缀是按「产物形态」切的，不是按业务切的。OA、ERP、CRM 这些包同样是 <code>comps-*</code>，没有独立前缀，容易在按前缀查表时被漏掉，这里单列一遍：</p><table tabindex="0"><thead><tr><th>方向</th><th>包</th><th>专题</th></tr></thead><tbody><tr><td>办公 / 进销存 / 客户关系</td><td><code>comps-vue3-oa</code>、<code>comps-vue3-erp</code>、<code>comps-vue3-crm</code></td><td><a href="./catalog/bizline.html">业务线组件</a></td></tr><tr><td>小说创作</td><td><code>comps-vue3-novel</code></td><td><a href="./catalog/novel.html">小说创作</a></td></tr><tr><td>数学与图形</td><td><code>comps-vue3-math</code></td><td><a href="./catalog/math.html">数学与图形</a></td></tr><tr><td>移动端 Vant</td><td><code>comps-vue3-vant</code>、<code>comps-vue3-vant-pro</code></td><td><a href="./catalog/vant.html">移动端组件</a></td></tr><tr><td>工业 / 医疗 / 金融</td><td><code>comps-vue3-iot</code>、<code>comps-vue3-med</code>、<code>comps-vue3-fin</code>、<code>comps-react-fin</code></td><td><a href="./components.html">组件包</a></td></tr><tr><td>大屏三维</td><td><code>comps-vue3-datav</code></td><td><a href="./catalog/datav.html">DataV</a>、<a href="./catalog/3d.html">3D 场景</a></td></tr></tbody></table><p>完整清单以<a href="./components.html">组件包</a>的专题表为准，这张表只标出按五类前缀查表时容易漏掉的业务线包。</p>`,14)])])}const u=e(c,[["render",s]]);export{i as __pageData,u as default};
